import {PARTS, INITIAL_INVENTORY, PROJECTS, missingParts, adjustInventory, recommendations, classifyQuestion, nextStep} from './model.js';
import {paintModel, paintTable} from './render.js';
import {resolveInteraction} from './interaction.js';

const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',blocks:'M3 9h18v12H3zM6 9V5h4v4m4 0V5h4v4M3 15h18M12 9v12',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',back:'m14 6-6 6 6 6M8 12h12',close:'m6 6 12 12M18 6 6 18',camera:'M8 6 9.5 3h5L16 6h5v14H3V6zM16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',mic:'M9 5a3 3 0 0 1 6 0v6a3 3 0 0 1-6 0zM5 10v1a7 7 0 0 0 14 0v-1M12 18v4m-4 0h8',sliders:'M4 5h16M4 12h16M4 19h16M8 2v6m8 1v6m-8 1v6',notebook:'M5 3h15v18H5zM2 7h6m-6 5h6m-6 5h6M11 7h5m-5 5h5',volume:'m3 9 5 0 5-5v16l-5-5H3zM17 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14',check:'m5 12 4 4L19 6',rotate:'M4 9a8 8 0 1 1 0 7M4 3v6h6',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',plus:'M12 5v14M5 12h14',minus:'M5 12h14',info:'M12 11v6m0-10v1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`}
const button=(a,label,kind='secondary',extra='')=>`<button class="${kind}" data-action="${a}" ${extra}>${label}</button>`;
const state={screen:'home',mode:'guide',project:'car',step:0,angle:-.7,highlight:false,selectedPart:null,selectedXY:null,inventory:{...INITIAL_INVENTORY},captured:false,photo:null,request:'자동차를 만들고 싶어',idea:'car',overlay:null,outcome:'normal',feedback:'실제 블록을 가리키며 질문해보세요.',sound:false,listening:false,participant:'P01',note:'',events:[],pendingQuestion:null,lastQuestion:'',questionSource:'',targetSource:'',orientationSource:''};
let paintCurrent=()=>{}, stream=null,recognizer=null,voicePurpose='question',hits=[],resizeObserver,returnFocus=null,toastTimer,animationFrame;
const current=()=>PROJECTS[state.project];
const step=()=>current().steps[Math.min(state.step,current().steps.length-1)];
function record(action,detail=''){state.events.push({time:new Date().toISOString(),screen:state.screen,step:state.screen==='guide'?state.step+1:null,action,detail});}
function toast(text){$('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=text;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500);}
function speak(text){if(state.sound&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';speechSynthesis.speak(u);}}
function feedback(text){state.feedback=text;$('#live-message').textContent=text;speak(text);}
function go(screen){stopListening();state.overlay=null;state.screen=screen;record('화면 이동',screen);render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function begin(id='car',mode='guide'){clearInteraction();state.project=id;state.mode=mode;state.step=0;state.angle=-.7;state.highlight=false;state.selectedPart=null;state.selectedXY=null;state.outcome='normal';feedback('실제 블록을 가리키며 질문해보세요. 진행자가 가리킨 대상을 대신 지정해요.');go('guide');}
function pageHeading(label,title,desc,side=''){return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>${side?`<div class="heading-side">${side}</div>`:''}</div>`;}
function model(type,cls='hero-visual',attrs=''){return `<div class="${cls}"><canvas data-model="${type}" ${attrs} role="img" aria-label="${esc(PROJECTS[type]?.title||'블록 모델')} 입체 예시"></canvas></div>`;}
function home(){return `<section class="home-hero"><div class="hero-copy"><div class="eyebrow">YOUR BUILDING COMPANION</div><h1>작은 블록 하나에서,<br><span>다음 아이디어까지.</span></h1><p class="description">헷갈리는 부품은 함께 확인하고,<br>가지고 있는 블록으로 새로운 작품을 시작해요.</p><div class="hero-spec">블록을 가리키고, 궁금한 점을 말해보세요.<br>필요한 순간에 조립 방법을 확인할 수 있어요.</div></div><div class="hero-visual"><div class="visual-note">${icon('blocks')} BUILD SOMETHING NEW</div><canvas data-model="car" role="img" aria-label="블록 자동차 입체 예시"></canvas><div class="visual-bottom"><span>작은 시티 자동차</span><span>인터랙션 예시 모델</span></div></div></section>${bodystormSetup()}<div class="home-section-title"><h2>어떻게 시작할까요?</h2><span>지금 필요한 도움을 선택하세요.</span></div><section class="mode-grid"><article class="mode-card featured"><div class="mode-heading"><div class="mode-icon">${icon('blocks')}</div><div><span class="mode-index">MODE 01</span><h3>설명서를 따라, 차근차근</h3></div></div><p>설명서 QR로 내 세트를 불러오세요.<br>필요한 부품과 연결 위치를 함께 확인해요.</p>${button('start-guide',`설명서 QR로 시작 ${icon('arrow')}`,'primary')}<div class="mini-flow"><span>부품 지정</span>${icon('chevron')}<span>비교·위치 확인</span>${icon('chevron')}<span>연결</span></div></article><article class="mode-card"><div class="mode-heading"><div class="mode-icon">${icon('spark')}</div><div><span class="mode-index">MODE 02</span><h3>내 블록으로, 자유롭게</h3></div></div><p>가지고 있는 블록을 확인하고 만들고 싶은 것을 말하면,<br>시작할 수 있는 작품을 함께 찾아요.</p>${button('start-create',`자유 창작 시작 ${icon('arrow')}`)}<div class="mini-flow"><span>보유 블록 확인</span>${icon('chevron')}<span>작품 선택</span>${icon('chevron')}<span>조립</span></div></article></section><div class="home-footnote">${icon('info')}<span>모드 1은 실제 손동작과 브라우저 음성 명령을 지원해요. 부품 종류 자동 식별과 모드 2의 추천은 포함하지 않습니다.</span></div>`;}
function camera(scan=false){return `<div class="panel camera-panel"><div class="panel-header"><span class="panel-title">${icon('camera')} ${scan?'보유 블록 살펴보기':'내 작업 공간'}</span><span class="hint">${scan?'블록을 겹치지 않게 펼쳐주세요':'실제 블록을 손가락으로 가리켜주세요'}</span></div><div class="camera-stage" id="camera-stage">${state.photo&&scan?`<img class="camera-shot" src="${state.photo}" alt="기기에서 촬영한 블록 사진">`:stream?'<video id="camera-video" autoplay muted playsinline aria-label="실제 카메라 영상"></video>':'<canvas id="table-canvas" tabindex="0" role="button" aria-label="예시 블록 화면. 클릭해 부품 지정, 키보드 Enter로 직접 선택"></canvas>'}<span class="camera-state">${state.photo&&scan?'내 사진 · 모의 분석':stream?'실제 영상 · 인식은 진행자 대행':'예시 화면 · 모의 인식'}</span>${state.selectedPart&&!scan&&state.selectedXY?`<div class="selection-target" style="left:${state.selectedXY.x}%;top:${state.selectedXY.y}%"><span>${esc(PARTS[state.selectedPart].name)}</span></div>`:''}${state.outcome==='occluded'&&!scan?'<div class="camera-error"><strong>부품이 가려져 있어요</strong><p>손을 잠시 떼거나 블록을 돌려 보여주세요. 조립 단계는 유지돼요.</p></div>':''}<span class="camera-label-bottom">${scan?'촬영 후 개수와 종류를 직접 수정할 수 있어요.':state.selectedPart?'가리킨 대상과 말한 질문을 함께 확인해요.':'참여자는 실물을 가리키고, 진행자가 대상을 대신 지정해요.'}</span></div><div class="camera-actions">${button(stream?'camera-off':'camera-on',icon('camera')+(stream?'카메라 끄기':'카메라 켜기'),'secondary small')}<span class="note">카메라 없이도 체험할 수 있어요.</span>${scan?button('capture',state.captured?'다시 확인':'블록 확인','secondary small'):button('open-operator','가리킨 대상 대행','text-button')}</div>${!scan?`<div class="required-parts"><div class="section-label"><span>이번 단계에 필요한 부품</span><span>${state.step+1} / ${current().steps.length}</span></div><div class="part-row"><canvas class="part-picture" data-part="${step().part}" aria-label="${esc(PARTS[step().part].name)}"></canvas><div><strong>${PARTS[step().part].name}</strong><small>${PARTS[step().part].detail}</small></div><span class="quantity">× ${step().qty}</span></div></div>`:''}</div>`;}
function guide(){return `${pageHeading(state.mode==='guide'?'GUIDED BUILD':'CREATIVE BUILD',current().title,'실물과 모델을 비교하며, 내 속도로 조립해요.',`STEP <strong>${String(state.step+1).padStart(2,'0')}</strong> / ${String(current().steps.length).padStart(2,'0')}`)}${multimodalStatus()}<div class="work-grid">${camera()}<div class="panel"><div class="panel-header"><span class="panel-title">${icon('blocks')} 단계별 입체 가이드</span><span class="hint">드래그하여 돌려보기</span></div><div class="guide-model"><canvas id="guide-canvas" data-model="${state.project}" data-step="${state.step}" data-rotate tabindex="0" aria-label="현재 조립 단계의 입체 예시. 드래그 또는 좌우 방향키로 회전"></canvas><span class="model-tip">${state.orientationSource?'실물 방향 대행 반영':state.highlight?'연결 위치 표시 중':'실물을 돌려 비교해보세요'}</span><div class="model-controls">${button('rotate-left',icon('left'),'icon-button','aria-label="왼쪽으로 회전"')}<span>돌려보기</span>${button('rotate-right',icon('right'),'icon-button','aria-label="오른쪽으로 회전"')}${button('rotate-reset',icon('rotate'),'icon-button','aria-label="모델 방향 초기화"')}</div></div><div class="step-instruction"><div class="step-kicker">${String(state.step+1).padStart(2,'0')} / ${String(current().steps.length).padStart(2,'0')}</div><h2>${step().title}</h2><p>${step().text}</p><div class="progress-track"><span style="width:${(state.step+1)/current().steps.length*100}%"></span></div><div class="step-navigation">${button('previous',`${icon('back')} 이전 단계`,'text-button',state.step===0?'disabled':'')}${button('next',`${state.step===current().steps.length-1?'조립 완료':'연결했어요'} ${icon('arrow')}`,'secondary small')}</div></div></div></div><section class="assistant-bar"><div class="assistant-content"><div class="assistant-symbol">${icon('spark')}</div><div><div class="assistant-state">${state.listening?'<span class="listening-dot"></span>듣고 있어요':'BLOCK MATE · 예시 응답'}</div><div class="assistant-message">${esc(state.feedback)}</div></div></div>${button('listen',`${icon('mic')} ${state.listening?'말하기 종료':'말로 질문하기'}`,'primary')}</section><div class="spoken-examples"><span>말하기 예시</span><strong>“이거 맞아?”</strong><strong>“어디에 끼워?”</strong><span>실물 블록을 가리키며 말해주세요.</span></div>${state.outcome==='occluded'?button('recover','다시 보여줄게','secondary small'):''}<details class="typed-question"><summary>음성 입력이 어려우면 화면으로 대신 입력</summary><div class="quick-questions">${button('ask-compare','이거 맞아?','question-button')}${button('ask-where','어디에 끼워?','question-button')}</div><form id="question-form" class="input-row"><input name="question" aria-label="조립 질문" placeholder="예: 이 두 부품은 무슨 차이야?" required maxlength="180"><button class="secondary small" type="submit">질문하기 ${icon('arrow')}</button></form></details><div class="home-footnote">${icon('info')}<span>부품 식별·방향 추적은 진행자가 대행해요. 실제 블록과 입체 예시의 차이를 검토하는 바디스토밍 시제품입니다.</span></div>`;}
function inventory(){if(!state.captured)return `<div class="inventory-unconfirmed"><div class="large-icon">${icon('blocks')}</div><h3>어떤 블록이 있나요?</h3><p>왼쪽에서 블록을 확인하면<br>예시 부품 목록이 나타나요.</p><p class="note">실제 사진에서도 준비된 목록을 불러와요.</p></div>`;return `<div class="inventory-header"><div><h3>확인한 블록</h3><p>실물과 다른 항목은 직접 고쳐주세요.</p></div><span class="muted">${Object.values(state.inventory).reduce((a,b)=>a+b,0)}개</span></div><div class="inventory-list">${Object.entries(PARTS).map(([id,p])=>`<div class="inventory-item"><canvas data-part="${id}" aria-label="${esc(p.name)}"></canvas><div><strong>${p.name}</strong><small>${p.detail}</small></div><div class="counter">${button('count',icon('minus'),'icon-button',`data-id="${id}" data-delta="-1" aria-label="${p.name} 개수 줄이기" ${state.inventory[id]===0?'disabled':''}`)}<output aria-label="${p.name} 개수">${state.inventory[id]}</output>${button('count',icon('plus'),'icon-button',`data-id="${id}" data-delta="1" aria-label="${p.name} 개수 늘리기"`)}</div></div>`).join('')}</div><p class="inventory-foot">사진에서 확실하지 않은 부품도 직접 확인해 반영해요.</p>`;}
function scan(){return `${pageHeading('FREE BUILD','내 블록에서 시작하는 새로운 작품','보유 부품을 먼저 확인한 뒤, 만들고 싶은 것을 알려주세요.','01 / 03 · 블록 확인')}<div class="scan-layout"><div>${camera(true)}<p class="scan-guide">${icon('info')} 펼치기 → 확인하기 → 부품 목록 수정하기</p></div><div class="panel inventory-panel">${inventory()}</div></div><section class="scan-request"><div class="row-between"><div><div class="eyebrow">WHAT WOULD YOU LIKE TO BUILD?</div><h2>무엇을 만들고 싶나요?</h2></div></div><form id="request-form"><div class="request-field"><input id="request-input" name="request" aria-label="만들고 싶은 작품" value="${esc(state.request)}" placeholder="예: 날개가 있는 자동차를 만들고 싶어" maxlength="150" required>${button('listen-request',icon('mic'),'icon-button',`aria-label="만들고 싶은 작품을 말하기" ${!state.captured?'disabled':''}`)}</div><div class="form-bottom"><span class="speech-note">${state.listening?'듣고 있어요. 다시 누르면 말하기를 마쳐요.':'예시 추천: 자동차, 로봇, 벤치 · 결과는 모의 처리됩니다.'}</span><button class="primary" type="submit" ${!state.captured?'disabled':''}>만들 수 있는 작품 보기 ${icon('arrow')}</button></div></form></section>`;}
function availability(id){const missing=missingParts(id,state.inventory);return `<span class="availability ${missing.length?'unavailable':''}">${icon(missing.length?'info':'check')}${missing.length?'부품 확인 필요':'내 블록으로 시작 가능'}</span>`;}
function ideas(){const p=PROJECTS[state.idea],missing=missingParts(state.idea,state.inventory),list=recommendations(state.request,state.inventory);return `${pageHeading('BUILD IDEAS','이런 작품부터 시작해볼까요?','확인한 부품과 요청을 기준으로 준비된 조립안을 보여드려요.','02 / 03 · 작품 선택')}<div class="request-summary">${icon('mic')}<strong>“${esc(state.request)}”</strong>${button('back-scan','요청 수정','text-button')}</div><div class="ideas-layout"><article class="panel idea-featured">${model(state.idea,'idea-visual','data-rotate tabindex="0"')}<div class="idea-copy"><div class="idea-title-row"><h2>${p.title}</h2>${availability(state.idea)}</div><p>${p.description}</p><div class="idea-specs"><span>${icon('blocks')}${Object.values(p.requires).reduce((a,b)=>a+b,0)}개 부품</span><span>${icon('eye')}${p.steps.length}단계 예시</span></div>${missing.length?`<div class="missing-list"><strong>이 부품이 더 필요해요.</strong>${missing.map(m=>`${PARTS[m.id].name} ${m.count}개`).join(' · ')}<br>목록을 수정하거나 다른 작품을 선택해보세요.</div>`:''}${button('build-idea',`이 작품 조립하기 ${icon('arrow')}`,'primary',missing.length?'disabled':'')}${missing.length?button('back-scan','보유 부품 다시 확인','text-button'):''}</div></article><div class="idea-alternatives">${list.filter(i=>i.id!==state.idea).map(({id})=>`<button class="idea-alternative" data-action="choose-idea" data-id="${id}"><div class="alternative-visual"><canvas data-model="${id}" aria-label="${PROJECTS[id].title} 예시"></canvas></div><div><h3>${PROJECTS[id].title}</h3><p>${PROJECTS[id].description}</p>${availability(id)}</div></button>`).join('')}<div class="idea-information"><h3>내가 확인한 부품으로</h3><p>부족한 블록이 있으면 먼저 알려드려요. 모양이 마음에 들지 않으면 다른 작품을 선택할 수 있어요.</p><details><summary>이 시제품의 추천 방식</summary><p>사진 분석이나 생성형 AI 대신 준비된 부품 목록과 세 가지 작품 예시를 사용해요. 요청에 따라 자동차·로봇·벤치를 우선 제안합니다.</p></details></div></div></div>`;}
function complete(){return `<section class="completion">${model(state.project)}<div class="completion-copy"><div class="eyebrow">BUILD COMPLETE</div><h1>하나의 아이디어가 완성됐어요.</h1><p>${current().title}의 가이드를 모두 확인했어요.<br>이 모양에서 새로운 작품으로 이어갈 수도 있어요.</p><div class="completion-actions">${button('continue-create',`내 블록으로 다른 작품 만들기 ${icon('arrow')}`,'primary')}${button('home','처음으로')}</div></div></section>`;}
function render(){resizeObserver?.disconnect();cancelAnimationFrame(animationFrame);const isCreate=state.mode==='create'&&['guide','complete'].includes(state.screen)||['scan','ideas'].includes(state.screen);$('#navigation').innerHTML=[['home','home','작업 공간'],['start-guide','blocks','조립 가이드'],['start-create','spark','자유 창작']].map(([action,i,t])=>button(action,icon(i)+`<span class="nav-text">${t}</span>`,'nav-item'+((action==='home'&&state.screen==='home'||action==='start-guide'&&!isCreate&&state.screen!=='home'||action==='start-create'&&isCreate)?' active':''),`aria-label="${t}"`)).join('')+(state.screen!=='home'?`<div class="sidebar-separator"></div><div class="nav-group-label">${isCreate?'CREATIVE JOURNEY':'BUILDING JOURNEY'}</div>${(isCreate?['블록 확인','작품 선택','함께 조립하기']:['부품 살펴보기','비교하고 질문하기','연결하고 확인하기']).map((s,i)=>`<div class="sub-step ${i===(isCreate?state.screen==='scan'?0:state.screen==='ideas'?1:2:state.highlight?2:state.selectedPart?1:0)?'current':''}"><span class="step-num">${i+1}</span>${s}</div>`).join('')}`:'');$('#breadcrumb').innerHTML=`작업 공간 ${icon('chevron')} <strong>${{home:'시작하기',guide:state.mode==='create'?'자유 창작 · 조립':'설명서 기반 조립',scan:'자유 창작 · 블록 확인',ideas:'자유 창작 · 작품 제안',complete:'조립 완료'}[state.screen]}</strong>`;$('#main').innerHTML=({home,guide,scan,ideas,complete}[state.screen])();$('#sound-button').classList.toggle('is-on',state.sound);$('#sound-button').setAttribute('aria-label',state.sound?'음성 안내 끄기':'음성 안내 켜기');$('#sound-button').setAttribute('aria-pressed',String(state.sound));document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));renderOverlay();setupCanvases();if(stream&&$('#camera-video'))$('#camera-video').srcObject=stream;sendOperatorState();}
function setupCanvases(){resizeObserver?.disconnect();const paint=()=>{document.querySelectorAll('canvas[data-model]').forEach(c=>paintModel(c,{type:c.dataset.model,step:c.dataset.step===undefined?99:Number(c.dataset.step),angle:state.angle,highlight:c.id==='guide-canvas'&&state.highlight}));document.querySelectorAll('canvas[data-part]').forEach(c=>paintModel(c,{part:c.dataset.part,angle:-.5}));if($('#table-canvas'))hits=paintTable($('#table-canvas'));};paintCurrent=paint;paint();resizeObserver=new ResizeObserver(paint);resizeObserver.observe($('#main'));document.querySelectorAll('canvas[data-rotate]').forEach(c=>{let start=null,base; c.addEventListener('pointerdown',e=>{start=e.clientX;base=state.angle;c.setPointerCapture(e.pointerId)});c.addEventListener('pointermove',e=>{if(start===null)return;state.angle=base+(e.clientX-start)*.012;paint();});c.addEventListener('pointerup',()=>{if(start!==null)record('모델 회전');start=null});c.addEventListener('pointercancel',()=>start=null);c.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();state.angle+=e.key==='ArrowLeft'?-.2:.2;paint();}})});$('#table-canvas')?.addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;const hit=[...hits].reverse().find(h=>Math.abs(x-h.x)<h.w/2&&Math.abs(y-h.y)<h.h/2);if(hit){selectPart(hit.id,{x:x/r.width*100,y:y/r.height*100});}else toast('블록 위를 선택하거나 ‘부품 직접 선택’을 눌러주세요.');});$('#table-canvas')?.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openOverlay('parts');}});$('#camera-video')?.addEventListener('click',()=>openOverlay('parts'));}
function selectPart(id,xy=null,source='화면으로 대신 입력') {
  state.selectedPart=id;state.selectedXY=xy;state.outcome='normal';state.targetSource=source;state.highlight=false;
  record('가리킨 대상 접수',`${PARTS[id].name} · ${source}`);
  if(state.pendingQuestion){const text=state.pendingQuestion;state.pendingQuestion=null;respondToQuestion(text);return;}
  state.lastQuestion='';state.questionSource='';
  feedback(`${PARTS[id].name}을 가리켰어요. 이제 궁금한 점을 말해주세요.`);render();
}
function openOverlay(name){returnFocus=document.activeElement;state.overlay=name;renderOverlay();}
function closeOverlay(){state.overlay=null;renderOverlay();returnFocus?.isConnected&&returnFocus.focus();}
function modal(title,body,actions=''){return `<div class="modal-backdrop" data-action="backdrop-close"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-heading"><h2 id="dialog-title">${title}</h2>${button('close',icon('close'),'icon-button','aria-label="닫기"')}</div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}</section></div>`;}
function renderOverlay(){const root=$('#overlay-root');let html='';if(state.overlay==='how')html=modal('두 사람이 함께 진행해요',`<div class="how-steps"><div><strong>1. 실제 블록 준비</strong><p>책상에 실제 블록과 조립 중인 물체를 놓고 화면을 옆에 배치해주세요.</p></div><div><strong>2. 가리키기 + 말하기</strong><p>참여자는 헷갈리는 블록을 손가락으로 가리키며 “이거 맞아?” 또는 “어디에 끼워?”라고 질문해요.</p></div><div><strong>3. 진행자가 입력 대행</strong><p>진행자는 시연 패널에서 가리킨 부품과 들은 질문을 각각 입력해요. 질문과 대상이 함께 들어오면 비교·위치 안내가 나와요.</p></div><div><strong>4. 돌려보고 연결하기</strong><p>참여자가 실물을 돌리면 진행자가 방향을 맞춰요. 안내를 보고 실제로 연결한 뒤 “연결했어”라고 말하면 다음 단계로 이동해요.</p></div></div><p>카메라와 마이크는 선택사항이에요. 자동 인식이 아니라 사람이 반응을 대행한다는 사실을 참여자에게 설명해주세요.</p>`,button('open-operator-window','진행자 창 열기','primary')+button('close','확인했어요'));if(state.overlay==='compare'){const match=state.selectedPart===step().part;html=modal(match?'필요한 부품과 같아요':'비슷하지만 다른 부품이에요',`<p>가리킨 대상과 말한 질문을 결합해 현재 단계의 부품과 비교한 예시예요.</p><div class="comparison-grid">${[[step().part,'이번 단계에 필요한 부품'],[state.selectedPart,'내가 지정한 부품']].map(([id,label])=>`<div class="comparison-item"><span>${label}</span><canvas data-part="${id}"></canvas><strong>${PARTS[id].name}</strong><small>${PARTS[id].detail}</small></div>`).join('')}</div><div class="comparison-result">${match?'형태와 크기가 같아요. 이제 연결할 위치를 확인해보세요.':`지정한 것은 ${PARTS[state.selectedPart].name}이에요. 이번에는 ${PARTS[step().part].name}을 찾아주세요.`}</div>`,button(match?'where-from-modal':'correct-part',match?'연결 위치 보기':'필요한 부품 다시 지정','primary'));}
if(state.overlay==='unknown')html=modal('아직 부품을 확인하기 어려워요',`<p>겹쳐 있거나 뒷면만 보이면 모양을 판단하기 어려울 수 있어요.</p><div class="comparison-result">블록을 다른 부품과 떨어뜨리고, 돌기가 보이도록 돌려 보여주세요. 직접 부품을 선택할 수도 있어요.</div>`,button('retry','다시 보여주기','primary')+button('manual-parts','직접 선택'));
if(state.overlay==='parts')html=modal('어떤 부품을 지정했나요?',`<p>이 시제품은 실제 부품을 자동으로 구별하지 않아요. 사용자가 가리킨 부품을 선택해주세요.</p><div class="manual-parts">${Object.entries(PARTS).map(([id,p])=>button('select-part',p.name,'secondary',`data-id="${id}"`)).join('')}</div>`);
if(state.overlay==='operator'||state.overlay==='notes'){const notes=state.overlay==='notes';html=`<div class="drawer-backdrop" data-action="close"></div><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-heading"><h2 id="dialog-title">${notes?'관찰 기록':'시연 패널'}</h2>${button('close',icon('close'),'icon-button','aria-label="닫기"')}</div><div class="drawer-content">${notes?notesPanel():operatorPanel()}</div></section>`;}
root.innerHTML=html;document.body.style.overflow=html?'hidden':'';root.querySelectorAll('canvas[data-part]').forEach(c=>paintModel(c,{part:c.dataset.part,angle:-.5}));if(html)root.querySelector('button,input,select')?.focus({preventScroll:true});}
function operatorPanel(){return `
<p class="drawer-intro">참여자는 실제 블록을 가리키고 질문해요. 진행자는 관찰한 입력만 대신 전달해주세요. 부품 식별·방향 추적·AI 답변은 모의 처리입니다.</p>
${button('open-operator-window',`${icon('sliders')} 진행자 창 따로 열기`,'secondary small')}
<p class="operator-hint">같은 브라우저의 새 창에서 조작하면 참여자 화면에 패널이 보이지 않아요. 다른 기기와는 연결되지 않습니다.</p>
<div class="control-group"><h3>지금 사용자 화면</h3><p>${state.screen==='guide'?`${current().title} · ${state.step+1}단계`:'조립 가이드를 시작해주세요.'}<br>가리킨 대상: ${state.selectedPart?PARTS[state.selectedPart].name:'아직 없음'}<br>말한 질문: ${esc(state.lastQuestion||'아직 없음')}${state.pendingQuestion?'<br><strong>대상 지정 대기 중</strong>':''}</p></div>
<div class="control-group"><h3>1. 사용자가 실제로 가리킨 부품</h3><div class="operator-parts">${Object.entries(PARTS).map(([id,p])=>button('op-target',p.name,'secondary small',`data-id="${id}"`)).join('')}</div><p>정답을 임의로 골라주지 말고, 참여자가 가리킨 부품을 그대로 선택해주세요.</p></div>
<div class="control-group"><h3>2. 사용자가 실제로 말한 질문</h3><div class="control-buttons">${button('op-question-compare','“이거 맞아?”','secondary small')}${button('op-question-where','“어디에 끼워?”','secondary small')}${button('op-question-next','“연결했어”','secondary small')}</div><p>마이크를 쓰기 어려울 때 발화를 대행해요. 질문과 대상은 어느 쪽을 먼저 입력해도 됩니다.</p></div>
<div class="control-group"><h3>3. 사용자가 실물을 돌린 방향</h3><div class="control-buttons">${button('op-turn-left','왼쪽으로 돌림','secondary small')}${button('op-turn-right','오른쪽으로 돌림','secondary small')}${button('op-turn-reset','정면으로 돌림','secondary small')}</div><p>진행자가 실물의 회전을 보고 모델 방향을 수동으로 맞춰요. 자동 추적이 아닙니다.</p></div>
<div class="control-group"><h3>인식 실패와 복구</h3><div class="control-buttons">${button('op-unknown','판단 불가','secondary small')}${button('op-occluded','손에 가려짐','secondary small')}${button('retry','다시 보여줌','secondary small')}${button('cancel-pending','질문·대상 초기화','secondary small')}</div></div>
<details class="control-group"><summary>장면 이동·창작 상황 설정</summary><div class="control-buttons" style="margin-top:12px">${button('op-guide','조립 시작','secondary small')}${button('op-scan','보유 블록 확인','secondary small')}${button('op-capture','블록 펼침 확인','secondary small')}${button('op-request','“자동차 만들고 싶어”','secondary small')}${button('op-ideas','작품 제안','secondary small')}${button('op-shortage','바퀴가 없는 상황','secondary small')}${button('op-inventory-reset','예시 부품 복원','secondary small')}</div></details>
<div class="control-group"><h3>관찰할 행동</h3><p>대상을 명확하게 가리켰는가?<br>대상을 가리키며 자연스럽게 질문했는가?<br>실물을 돌렸을 때 화면과 방향을 연결했는가?<br>화면을 터치하지 않고 도움을 얻었는가?</p></div>`;}

function notesPanel(){return `<p class="drawer-intro">기록은 이 탭 안에서만 유지돼요. 종료 전에 파일로 내려받아주세요. 사진·음성 원본은 기록하지 않습니다.</p><div class="control-group"><label for="participant">참여자 코드</label><input id="participant" value="${esc(state.participant)}" maxlength="30"><label for="observation" style="margin-top:14px">관찰 내용</label><textarea id="observation" placeholder="예: 2단계에서 짧은 블록을 들고 ‘이거 맞아?’라고 질문함.">${esc(state.note)}</textarea><div class="control-buttons" style="margin-top:10px">${button('save-note','기록 추가','secondary small')}${button('export',`${icon('download')} 기록 내려받기`,'secondary small')}</div></div><div class="control-group"><h3>행동 기록 · ${state.events.length}건</h3>${state.events.length?`<ol class="event-list">${state.events.slice(-40).reverse().map(e=>`<li><time>${new Date(e.time).toLocaleTimeString('ko-KR',{hour12:false,hour:'2-digit',minute:'2-digit'})}</time><span><strong>${esc(e.action)}</strong>${e.detail?`<br>${esc(e.detail)}`:''}</span></li>`).join('')}</ol>`:'<div class="empty-events">아직 기록된 행동이 없어요.</div>'}</div>`;}
async function cameraOn(){try{if(!navigator.mediaDevices?.getUserMedia)throw new Error('unsupported');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment',width:{ideal:1280}},audio:false});state.photo=null;record('카메라 켜기');render();}catch(error){record('카메라 접근 실패',error.name||error.message);toast(error.name==='NotAllowedError'?'카메라 권한이 허용되지 않았어요. 예시 화면으로 계속할 수 있어요.':'카메라를 사용할 수 없어요. 예시 화면으로 계속해주세요.');}}
function cameraOff(){stream?.getTracks().forEach(t=>t.stop());stream=null;record('카메라 끄기');render();}
function capture(){if(stream&&$('#camera-video')){const v=$('#camera-video');if(v.videoWidth){const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);state.photo=c.toDataURL('image/jpeg',.7);}}state.captured=true;record('보유 블록 확인','예시 목록 불러오기');render();toast('예시 목록을 불러왔어요. 실제 부품과 비교해 수정해주세요.');}
function ask(text,source='화면으로 대신 입력') {
  state.overlay=null;state.lastQuestion=text;state.questionSource=source;
  record('질문 접수',`${text} · ${source}`);respondToQuestion(text);
}
function respondToQuestion(text) {
  const result=resolveInteraction(text,state.selectedPart,state.outcome,step().part);
  if(result==='await-target') {
    state.pendingQuestion=text;
    feedback('질문을 들었어요. 어떤 블록인지 가리켜주세요. 진행자가 대상을 지정하면 답변을 이어가요.');render();return;
  }
  if(result==='retry') {
    state.pendingQuestion=text;state.overlay='unknown';
    feedback('가리킨 부품을 확인하기 어려워요. 블록을 돌려 다시 보여주세요. 질문과 조립 단계는 유지해요.');render();return;
  }
  state.pendingQuestion=null;
  if(result==='compare') {
    state.highlight=false;
    record('제스처·음성 결합',`${PARTS[state.selectedPart].name} + ${text}`);
    record('부품 비교',state.selectedPart===step().part?'일치':'불일치');
    feedback(state.selectedPart===step().part?'필요한 부품과 같아요. 연결 위치를 확인해보세요.':'다른 부품이에요. 필요한 부품과 나란히 비교해보세요.');
    state.overlay='compare';render();return;
  }
  if(result==='where') {
    state.highlight=true;record('제스처·음성 결합',`${PARTS[state.selectedPart].name} + ${text}`);
    feedback(step().text+' 실물을 돌려보면 진행자가 모델 방향을 맞춰줄 수 있어요.');
    record('연결 위치 확인');render();animateConnection();return;
  }
  if(result==='next'){advance();return;}
  feedback('지금은 “이거 맞아?”, “어디에 끼워?”, “연결했어”를 시연할 수 있어요.');render();
}

function animateConnection(){const c=$('#guide-canvas');if(!c)return;const start=performance.now(),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;function frame(now){const p=reduce?1:Math.min(1,(now-start)/900);paintModel(c,{type:state.project,step:state.step,angle:state.angle,highlight:true,animation:p});if(p<1)animationFrame=requestAnimationFrame(frame);}animationFrame=requestAnimationFrame(frame);}
function advance(){const n=nextStep(state.step,state.project);record('단계 완료',String(state.step+1));if(n===current().steps.length){go('complete');return;}state.step=n;resetStep();}
function resetStep(){clearInteraction();state.selectedPart=null;state.selectedXY=null;state.highlight=false;state.outcome='normal';feedback('새로운 단계예요. 필요한 부품을 확인하고, 궁금한 점을 질문해보세요.');render();}
function stopListening(){if(recognizer){recognizer.abort();recognizer=null;}state.listening=false;}
function listen(purpose='question'){if(state.listening){recognizer?.stop();return;}const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){toast('이 브라우저에서는 음성 입력을 지원하지 않아요. 실제로 질문하면 진행자가 발화를 대신 입력할 수 있어요.');return;}voicePurpose=purpose;const rec=new Speech();recognizer=rec;rec.lang='ko-KR';rec.interimResults=false;rec.continuous=false;state.listening=true;render();rec.onresult=e=>{const text=e.results[0][0].transcript;state.listening=false;recognizer=null;record('음성 입력',text);if(voicePurpose==='request'){state.request=text;render();}else ask(text,'음성 인식');};rec.onerror=e=>{state.listening=false;recognizer=null;record('음성 입력 실패',e.error);render();toast(e.error==='not-allowed'?'마이크 권한을 확인하거나 직접 입력해주세요.':'음성을 확인하지 못했어요. 진행자가 발화를 대신 입력해 계속할 수 있어요.');};rec.onend=()=>{if(recognizer===rec){state.listening=false;recognizer=null;render();}};try{rec.start();}catch{state.listening=false;recognizer=null;render();toast('음성을 시작할 수 없어요. 직접 입력을 이용해주세요.');}}
function showIdeas(){state.idea=/로봇/.test(state.request)?'robot':/벤치|의자/.test(state.request)?'bench':/날개/.test(state.request)?'wingcar':'car';go('ideas');}
const actions={home:()=>go('home'),'start-guide':()=>{location.href=new URL('./import-set.html',location.href).href;},'start-create':()=>{state.mode='create';go('scan');},'open-operator':()=>openOverlay('operator'),'open-notes':()=>openOverlay('notes'),close:closeOverlay,'backdrop-close':e=>{if(e.target===e.currentTarget)closeOverlay();},'toggle-sound':()=>{state.sound=!state.sound;if(!state.sound)window.speechSynthesis?.cancel();render();toast(state.sound?'음성 안내를 켰어요.':'음성 안내를 껐어요.');},'camera-on':cameraOn,'camera-off':cameraOff,capture,'manual-parts':()=>openOverlay('parts'),'select-part':e=>{state.overlay=null;selectPart(e.currentTarget.dataset.id);},'ask-compare':()=>ask('이거 맞아?'),'ask-where':()=>ask('어디에 끼워?'),listen:()=>listen(),'listen-request':()=>listen('request'),'where-from-modal':()=>{state.overlay=null;ask('어디에 끼워?');},'correct-part':()=>{state.overlay='parts';renderOverlay();},retry:()=>{state.outcome='normal';state.selectedPart=null;state.selectedXY=null;state.targetSource='';state.overlay=null;feedback(state.pendingQuestion?'질문을 기억하고 있어요. 다시 보여준 블록을 진행자가 지정해주세요.':'블록을 다시 가리켜주세요. 현재 조립 단계는 유지돼요.');record('인식 재시도');render();},recover:()=>{state.outcome='normal';record('가림 상태 복구');feedback('작업 화면이 돌아왔어요. 블록을 다시 지정하고 질문해주세요.');render();},next:advance,previous:()=>{if(state.step>0){state.step--;record('이전 단계');resetStep();}},'rotate-left':()=>{state.angle-=.3;paintCurrent();},'rotate-right':()=>{state.angle+=.3;paintCurrent();},'rotate-reset':()=>{state.angle=-.7;paintCurrent();},count:e=>{const{id,delta}=e.currentTarget.dataset;state.inventory=adjustInventory(state.inventory,id,Number(delta));record('부품 개수 수정',`${PARTS[id].name}: ${state.inventory[id]}`);render();},'back-scan':()=>go('scan'),'choose-idea':e=>{state.idea=e.currentTarget.dataset.id;record('작품 선택',PROJECTS[state.idea].title);render();},'build-idea':()=>{if(!missingParts(state.idea,state.inventory).length)begin(state.idea,'create');},'continue-create':()=>{state.mode='create';state.captured=true;go('scan');},'op-guide':()=>begin(),'op-scan':()=>{state.mode='create';go('scan');},'op-ideas':()=>{state.mode='create';state.captured=true;showIdeas();},'op-correct':()=>{if(state.screen!=='guide'){begin();}state.overlay=null;selectPart(step().part);},'op-wrong':()=>{if(state.screen!=='guide')begin();state.overlay=null;selectPart(step().part==='brick2'?'brick4':'brick2');},'op-unknown':()=>{if(state.screen!=='guide')begin();state.outcome='unknown';state.overlay='unknown';record('인식 판단 불가');render();},'op-occluded':()=>{if(state.screen!=='guide')begin();state.outcome='occluded';state.overlay=null;feedback('손에 가려진 부품을 확인하기 어려워요. 블록을 돌려 보여주거나 직접 선택해주세요.');record('부품 가림');render();},'op-shortage':()=>{state.inventory={...state.inventory,wheel:0};state.captured=true;state.mode='create';state.overlay=null;state.idea='car';state.request='자동차를 만들고 싶어';go('ideas');toast('바퀴가 없는 상황으로 바꿨어요.');},'op-inventory-reset':()=>{state.inventory={...INITIAL_INVENTORY};record('예시 부품 복원');render();toast('예시 부품 목록을 복원했어요.');},'save-note':()=>{if(!state.note.trim()){toast('관찰 내용을 입력해주세요.');return;}record('관찰 메모',state.note.trim());state.note='';renderOverlay();toast('관찰 내용을 추가했어요.');},export:()=>{const data={project:'BLOCK MATE',participant:state.participant,exportedAt:new Date().toISOString(),unsavedNote:state.note,events:state.events};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`block-mate-${state.participant.replace(/[^a-zA-Z0-9_-]/g,'_')||'session'}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('관찰 기록을 내려받았어요.');}};
Object.assign(actions,{
  'open-how':()=>openOverlay('how'),
  'cancel-pending':()=>{clearInteraction();state.overlay=null;feedback('질문과 대상을 비웠어요. 블록을 다시 가리키며 질문해주세요.');record('질문·대상 초기화');render();},
  'op-target':e=>{ensureGuide();state.overlay=null;selectPart(e.currentTarget.dataset.id,null,'진행자 대행');},
  'op-question-compare':()=>{ensureGuide();ask('이거 맞아?','진행자 대행');},
  'op-question-where':()=>{ensureGuide();ask('어디에 끼워?','진행자 대행');},
  'op-question-next':()=>{ensureGuide();ask('연결했어','진행자 대행');},
  'op-turn-left':()=>turnPhysical(-Math.PI/6),
  'op-turn-right':()=>turnPhysical(Math.PI/6),
  'op-turn-reset':()=>turnPhysical(null),
  'op-capture':()=>{if(state.screen!=='scan'){state.mode='create';go('scan');}capture();},
  'op-request':()=>{state.request='자동차를 만들고 싶어';state.captured=true;state.mode='create';record('창작 발화 대행',state.request);showIdeas();},
  'open-operator-window':openOperatorWindow,
});
function clearInteraction(){state.pendingQuestion=null;state.lastQuestion='';state.questionSource='';state.targetSource='';state.orientationSource='';state.selectedPart=null;state.selectedXY=null;}
function ensureGuide(){if(state.screen!=='guide')begin();}
function turnPhysical(delta){ensureGuide();state.overlay=null;state.angle=delta===null?-.7:state.angle+delta;state.orientationSource='진행자 대행';record('실물 회전 대행',delta===null?'정면':delta<0?'왼쪽':'오른쪽');feedback('진행자가 실물 방향에 맞춰 모델을 돌렸어요. 연결할 면을 비교해보세요.');render();}
function bodystormSetup(){return `<section class="bodystorm-setup"><div><span class="eyebrow">MODE 01 · LIVE PROTOTYPE</span><h2>손으로 회전하고, 분해해서 살펴보세요.</h2><p>조립 상태와 가이드 조작을 구분하고, 음성으로 고정 시점을 요청할 수 있어요.</p></div><div class="setup-roles"><div><strong>한 손 집기</strong><span>모델 회전</span></div><div><strong>두 손 집기</strong><span>분해도 조절</span></div></div>${button('start-guide','모드 1 사용하기','secondary small')}</section>`;}

function multimodalStatus(){return `<section class="multimodal-status" aria-label="제스처와 음성 입력 상태"><div class="multimodal-heading"><strong>실제 블록을 가리키고, 궁금한 점을 말해주세요.</strong>${button('open-how','진행 방법','text-button')}</div><div class="modality-grid"><div class="modality ${state.selectedPart?'ready':''}"><span>${icon('eye')} 가리킨 대상</span><strong>${state.selectedPart?PARTS[state.selectedPart].name:'실물 블록을 가리켜주세요'}</strong><small>${state.targetSource||'진행자가 관찰한 대상을 지정해요'}</small></div><span class="modality-plus">+</span><div class="modality ${state.lastQuestion?'ready':''}"><span>${icon('mic')} 말한 질문</span><strong>${state.lastQuestion?'“'+esc(state.lastQuestion)+'”':'“이거 맞아?”라고 말해보세요'}</strong><small>${state.questionSource||'음성 입력 또는 진행자 발화 대행'}</small></div><span class="modality-plus">→</span><div class="modality"><span>${icon('spark')} 응답 상태</span><strong>${state.pendingQuestion?'가리킨 대상 확인 중':state.overlay==='compare'?'부품 비교':state.highlight?'연결 위치 안내':state.selectedPart&&state.lastQuestion?'입력 결합 완료':'제스처와 질문을 기다려요'}</strong><small>${state.pendingQuestion?'질문을 유지한 채 대상을 기다려요':'인식·AI 답변은 바디스토밍 모의 처리'}</small></div></div>${state.pendingQuestion?button('cancel-pending','질문 취소','text-button'):''}</section>`;}

// Only minimal scene state is shared between same-origin tabs. No images or notes.
const operatorChannel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('block-mate-bodystorm-v2'):null;
const participantSession=window.crypto?.randomUUID?.()||String(Date.now());
function sendOperatorState(){operatorChannel?.postMessage({type:'state',session:participantSession,screen:state.screen,project:state.project,step:state.step,selectedPart:state.selectedPart,lastQuestion:state.lastQuestion,pendingQuestion:state.pendingQuestion,angle:state.angle,feedback:state.feedback});}
function dispatchAction(action,data={},event=null){const fn=actions[action];if(!fn)return;fn(event||{target:null,currentTarget:{dataset:data}});sendOperatorState();}
const remoteActions=new Set(['op-target','op-question-compare','op-question-where','op-question-next','op-turn-left','op-turn-right','op-turn-reset','op-unknown','op-occluded','retry','cancel-pending','op-guide','op-scan','op-capture','op-request','op-ideas','op-shortage','op-inventory-reset','close']);
operatorChannel?.addEventListener('message',e=>{const m=e.data;if(m?.type==='hello'){sendOperatorState();return;}if(m?.type!=='action'||m.session!==participantSession||!remoteActions.has(m.action))return;if(m.action==='op-target'&&!PARTS[m.data?.id])return;dispatchAction(m.action,m.data||{});});
function openOperatorWindow(){if(!operatorChannel){toast('진행자 창 연결을 지원하지 않아 현재 패널에서 진행해주세요.');return;}const url=new URL('./operator.html',location.href);const popup=window.open(url.href,'blockmate-facilitator','popup,width=520,height=820');if(!popup){toast('팝업이 차단됐어요. 이 시연 패널에서 대신 조작할 수 있어요.');return;}closeOverlay();record('진행자 창 열기');}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=actions[el.dataset.action];if(action){e.preventDefault();dispatchAction(el.dataset.action,el.dataset,{target:e.target,currentTarget:el});}});
document.addEventListener('submit',e=>{if(e.target.id==='question-form'){e.preventDefault();ask(new FormData(e.target).get('question'),'직접 입력');}if(e.target.id==='request-form'){e.preventDefault();if(!state.captured)return;state.request=String(new FormData(e.target).get('request')).trim();if(state.request)showIdeas();}});
document.addEventListener('input',e=>{if(e.target.id==='request-input')state.request=e.target.value;if(e.target.id==='participant')state.participant=e.target.value;if(e.target.id==='observation')state.note=e.target.value;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.overlay){closeOverlay();return;}if(e.key==='Tab'&&state.overlay){const els=[...$('#overlay-root').querySelectorAll('button:not(:disabled),input,select,textarea,[tabindex="0"]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('pagehide',()=>operatorChannel?.postMessage({type:'bye',session:participantSession}));
window.addEventListener('beforeunload',()=>{stream?.getTracks().forEach(t=>t.stop());recognizer?.abort();window.speechSynthesis?.cancel();});
record('체험 시작');render();
